s = io.open(p, encoding='utf-8').read()
L = s.split('\n')
out = []
fails = []
def chk(n, c):
    out.append(('PASS' if c else 'FAIL') + ' ' + n)
    if not c:
        fails.append(n)
def cells(l):
    return [x.strip() for x in l.strip().strip('|').split('|')]

# T2 numeric rows (14 cells)
t2 = {}
for l in L:
    if l.count('|') != 15:
        continue
    c = cells(l)
    if c[0] in ('P1', 'P2', 'P3'):
        t2[c[0]] = c
for per, c in t2.items():
    A, B, C, D, E, F, G = [int(x) for x in c[1:8]]
    for i, (n, d) in enumerate([(B, A), (C, A), (D, C), (E, D), (F, B), (G, E)]):
        exp = float(c[8 + i].split('= ')[1].rstrip('%'))
        chk('T2 %s rate[%d] %d/%d=%.1f%%' % (per, i, n, d, round(n / d * 100, 1)), abs(round(n / d * 100, 1) - exp) < 0.05)
    chk('T2 %s nest G<=E<=D<=C<=A' % per, G <= E <= D <= C <= A)
    chk('T2 %s nest F<=B<=A' % per, F <= B <= A)
m = [cells(l) for l in L if l.startswith('| 合併（口徑不一')][0]
for idx in range(1, 8):
    chk('T2 merged col%d' % idx, int(m[idx]) == sum(int(t2[x][idx]) for x in ('P1', 'P2', 'P3')))
chk('T2 P3Q2 A=14 info', '| 14 | — | — | — | — | — | — |' in s)

# T4
for l in L:
    if l.count('|') == 11 and l.startswith('| P') or False:
        pass
t4 = {}
for l in L:
    c = cells(l) if l.count('|') == 11 else None
    if not c:
        continue
    if c[0] in ('P1', 'P2', 'P3') and c[1] in ('24', '32', '18'):
        t4[c[0]] = c
for per, c in t4.items():
    D, E, a, b, cc, G = [int(c[i]) for i in (1, 2, 3, 4, 5, 6)]
    chk('T4 %s A+B+C=E' % per, a + b + cc == E)
    chk('T4 %s G=TierA+TierB' % per, G == a + b)
    chk('T4 %s G/E' % per, abs(round(G / E * 100, 1) - float(c[7].split('= ')[1].rstrip('%'))) < 0.05)

# T5
for per, D, E in [('P1', 24, 15), ('P2', 32, 22), ('P3', 18, 11)]:
    rows = [cells(l) for l in L if re.match(r'^\| ' + per + r' \| (有陪伴|無陪伴)', l)]
    chk('T5 %s sumD' % per, sum(int(r[2]) for r in rows) == D)
    chk('T5 %s sumE' % per, sum(int(r[3]) for r in rows) == E)
    for r in rows:
        chk('T5 %s %s rate' % (per, r[1]), abs(round(int(r[3]) / int(r[2]) * 100, 1) - float(r[4].split('= ')[1].rstrip('%'))) < 0.05)
mr = [cells(l) for l in L if re.match(r'^\| 合併（描述性） \| (有陪伴|無陪伴)', l)]
chk('T5 merged sumD=74', sum(int(r[2]) for r in mr) == 74)
chk('T5 merged sumE=48', sum(int(r[3]) for r in mr) == 48)
chk('T5 P3 gap 25.0', abs((75.0 - 50.0) - 25.0) < 1e-9)

# T6
t6 = {}
for l in L:
    c = cells(l) if l.count('|') == 8 else None
    if not c:
        continue
    if c[0] in ('P1', 'P2', 'P3') and c[1] in ('32', '40', '25'):
        t6[c[0]] = c
for per, c in t6.items():
    chk('T6 %s 未涵蓋=C-D' % per, int(c[1]) - int(c[2]) == int(c[3]))
    chk('T6 %s 失聯+拒訪=C-D' % per, int(c[4]) + int(c[5]) == int(c[3]))

# schema consistency
chk('T3 評量題數 removed', not any(l.startswith('| 評量題數') for l in L))
chk('T3 canonical names', any(l.startswith('| 滿分 |') for l in L) and any(l.startswith('| 總分門檻 |') for l in L))
chk('T3 example header canonical', '| period_id | 能力項 | 滿分 | 總分門檻 | 該期達標率 |' in s)
chk('T8 schema header present', '| 陪伴組應用率 | 比率（`T5` 有陪伴列） |' in s)
chk('T8 example header', '| period_id | 能力達標率 | 主要應用率（T+90） | 非自述佐證占率 | 陪伴組應用率 | 無陪伴組應用率 |' in s)

# register atomicity: no value cell (col 5) contains bundle separators for case rows
for i in ['184', '186', '188', '191', '192', '194', '195', '198', '199', '200', '201', '204']:
    row = [l for l in L if l.startswith('| SF-0057-' + i + ' ')]
    chk('reg row %s exists' % i, len(row) == 1)
    if row:
        v = cells(row[0])[5]
        chk('reg row %s no ；bundle' % i, '；' not in v)
        chk('reg row %s no 、bundle' % i, '、' not in v)

# dates
def d(x):
    return datetime.date(*map(int, x.split('-')))
for n, a, b in [('P1 T+90', '2024-12-31', '2025-03-31'), ('P2 T+90', '2025-12-31', '2026-03-31'),
                ('P3 T+90', '2026-03-31', '2026-06-29'), ('P3 T+180', '2026-03-31', '2026-09-27'),
                ('P3Q2 earliest T+90', '2026-04-02', '2026-07-01'), ('P3Q2 latest T+90', '2026-06-26', '2026-09-24'),
                ('P3Q2 latest T+180', '2026-06-26', '2026-12-23'), ('P2 T+180', '2025-12-31', '2026-06-29')]:
    days = int(b and (d(b) - d(a)).days)
    chk('%s (%s..%s = %d days)' % (n, a, b, days), days in (90, 180))
for n, off, a, b in [('case T+30', 30, '2025-03-15', '2025-04-14'), ('case T+60', 60, '2025-03-15', '2025-05-14'),
                     ('case T+90', 90, '2025-03-15', '2025-06-13'), ('case T+180', 180, '2025-03-15', '2025-09-11')]:
    chk('%s' % n, (d(b) - d(a)).days == off)

io.open(r'C:\Users\J\AppData\Local\Temp\opencode\chk_out.txt', 'w', encoding='utf-8').write('\n'.join(out) + '\n\nTOTAL %d, FAILS %d\n' % (len(out), len(fails)) + ('\n'.join(fails)))
print('checks', len(out), 'fails', len(fails))
for f in fails:
    print('FAIL', f)

